// SVF flags (from g_public.h)
const SVF_GLASS_BRUSH: c_int = 0x08000000; // Ent is a glass brush

// SCF script flags (from b_public.h)
const SCF_DONT_FLEE: c_int = 0x00008000; // NPC never flees

/// Vector comparison helper — returns 1 if vectors are equal, 0 otherwise.
fn vector_compare(v1: vec3_t, v2: vec3_t) -> bool {
    v1[0] == v2[0] && v1[1] == v2[1] && v1[2] == v2[2]
}

/// Raven `G_ClearLineOfSight`.
///
/// Raven: "returns true if can see from point 1 to 2, even through glass (1
/// pane)- doesn't work with portals".
/// Source: `oracle/oracle/codemp/game/NPC_senses.c:11-36`
pub fn G_ClearLineOfSight(
    ctx: GameContext<'_>,
    point1: vec3_t,
    point2: vec3_t,
    ignore: c_int,
    clipmask: c_int,
) -> qboolean {
    let mut tr = trace_t::default();
    trap::Trace(
        ctx.engine,
        &mut tr as *mut trace_t,
        &point1 as *const vec3_t,
        core::ptr::null(),
        core::ptr::null(),
        &point2 as *const vec3_t,
        ignore,
        clipmask,
    );

    if tr.fraction == 1.0 {
        return 1;
    }

    let hit = unsafe { &mut ctx.world.cast_mut().entities[tr.entityNum as usize] };

    if EntIsGlass(hit) {
        let mut newpoint1 = tr.endpos;
        trap::Trace(
            ctx.engine,
            &mut tr as *mut trace_t,
            &newpoint1 as *const vec3_t,
            core::ptr::null(),
            core::ptr::null(),
            &point2 as *const vec3_t,
            hit.s.number,
            clipmask,
        );

        if tr.fraction == 1.0 {
            return 1;
        }
    }

    0
}

/// Raven `CanSee`.
///
/// Raven: determine if NPC can see an entity. This is a straight line trace
/// check. This function does not look at PVS or FOV, or take any AI related
/// factors (for example, the NPC's reaction time) into account.
/// Source: `oracle/oracle/codemp/game/NPC_senses.c:47-80`
pub fn CanSee(
    ctx: GameContext<'_>,
    ent: *mut gentity_t,
) -> qboolean {
    let mut tr = trace_t::default();
    let mut eyes = [0.0; 3];
    let mut spot = [0.0; 3];

    let npc = unsafe { ctx.world.cast_mut().globals.NPC };
    CalcEntitySpot(ctx, npc, spot_t::SPOT_HEAD_LEAN, &mut eyes);

    CalcEntitySpot(ctx, ent, spot_t::SPOT_ORIGIN, &mut spot);
    trap::Trace(
        ctx.engine,
        &mut tr as *mut trace_t,
        &eyes as *const vec3_t,
        core::ptr::null(),
        core::ptr::null(),
        &spot as *const vec3_t,
        unsafe { (*npc).s.number },
        MASK_OPAQUE,
    );
    ShotThroughGlass(ctx, &mut tr as *mut trace_t, ent, spot, MASK_OPAQUE);
    if tr.fraction == 1.0 {
        return 1;
    }

    CalcEntitySpot(ctx, ent, spot_t::SPOT_HEAD, &mut spot);
    trap::Trace(
        ctx.engine,
        &mut tr as *mut trace_t,
        &eyes as *const vec3_t,
        core::ptr::null(),
        core::ptr::null(),
        &spot as *const vec3_t,
        unsafe { (*npc).s.number },
        MASK_OPAQUE,
    );
    ShotThroughGlass(ctx, &mut tr as *mut trace_t, ent, spot, MASK_OPAQUE);
    if tr.fraction == 1.0 {
        return 1;
    }

    CalcEntitySpot(ctx, ent, spot_t::SPOT_LEGS, &mut spot);
    trap::Trace(
        ctx.engine,
        &mut tr as *mut trace_t,
        &eyes as *const vec3_t,
        core::ptr::null(),
        core::ptr::null(),
        &spot as *const vec3_t,
        unsafe { (*npc).s.number },
        MASK_OPAQUE,
    );
    ShotThroughGlass(ctx, &mut tr as *mut trace_t, ent, spot, MASK_OPAQUE);
    if tr.fraction == 1.0 {
        return 1;
    }

    0
}

/// Raven `InFront`.
///
/// Source: `oracle/oracle/codemp/game/NPC_senses.c:82-98`
pub fn InFront(
    spot: vec3_t,
    from: vec3_t,
    fromAngles: vec3_t,
    threshHold: f32,
) -> qboolean {
    let mut dir = [0.0; 3];
    let mut forward = [0.0; 3];
    let mut angles = [0.0; 3];
    let dot: f32;

    _VectorSubtract(spot, from, &mut dir);
    dir[2] = 0.0;
    VectorNormalize(&mut dir);

    _VectorCopy(fromAngles, &mut angles);
    angles[0] = 0.0;
    AngleVectors(angles, Some(&mut forward), None, None);

    dot = DotProduct(dir, forward);

    if dot > threshHold { 1 } else { 0 }
}

/// Raven `InFOV3`.
///
/// Raven: IDEA: further off to side of FOV range, higher chance of failing
/// even if technically in FOV, keep core of 50% to sides as always
/// succeeding.
/// Source: `oracle/oracle/codemp/game/NPC_senses.c:109-125`
pub fn InFOV3(
    spot: vec3_t,
    from: vec3_t,
    fromAngles: vec3_t,
    hFOV: c_int,
    vFOV: c_int,
) -> qboolean {
    let mut deltaVector = [0.0; 3];
    let mut angles = [0.0; 3];
    let mut deltaAngles = [0.0; 3];

    _VectorSubtract(spot, from, &mut deltaVector);
    vectoangles(deltaVector, &mut angles);

    deltaAngles[0] = AngleDelta(fromAngles[0], angles[0]);
    deltaAngles[1] = AngleDelta(fromAngles[1], angles[1]);

    if deltaAngles[0].abs() <= vFOV as f32 && deltaAngles[1].abs() <= hFOV as f32 {
        1
    } else {
        0
    }
}

/// Raven `InFOV2`.
///
/// Raven: NPC to position.
/// Source: `oracle/oracle/codemp/game/NPC_senses.c:129-145`
pub fn InFOV2(
    ctx: GameContext<'_>,
    origin: vec3_t,
    from: *mut gentity_t,
    hFOV: c_int,
    vFOV: c_int,
) -> qboolean {
    let mut fromAngles = [0.0; 3];
    let mut eyes = [0.0; 3];

    if unsafe { !(*from).client.is_null() } {
        _VectorCopy(
            unsafe { (*(*from).client).ps.viewangles },
            &mut fromAngles,
        );
    } else {
        _VectorCopy(unsafe { (*from).s.angles }, &mut fromAngles);
    }

    CalcEntitySpot(ctx, from, spot_t::SPOT_HEAD, &mut eyes);

    InFOV3(origin, eyes, fromAngles, hFOV, vFOV)
}

/// Raven `InFOV`.
///
/// Raven: Entity to entity.
/// Source: `oracle/oracle/codemp/game/NPC_senses.c:149-208`
pub fn InFOV(
    ctx: GameContext<'_>,
    ent: *mut gentity_t,
    from: *mut gentity_t,
    hFOV: c_int,
    vFOV: c_int,
) -> qboolean {
    let mut eyes = [0.0; 3];
    let mut spot = [0.0; 3];
    let mut deltaVector = [0.0; 3];
    let mut angles = [0.0; 3];
    let mut fromAngles = [0.0; 3];
    let mut deltaAngles = [0.0; 3];

    if unsafe { !(*from).client.is_null() } {
        // Check if renderInfo.eyeAngles is not zero
        if !vector_compare(
            unsafe { (*(*from).client).renderInfo.eyeAngles },
            vec3_origin,
        ) {
            // Actual facing of tag_head!
            _VectorCopy(
                unsafe { (*(*from).client).renderInfo.eyeAngles },
                &mut fromAngles,
            );
        } else {
            _VectorCopy(
                unsafe { (*(*from).client).ps.viewangles },
                &mut fromAngles,
            );
        }
    } else {
        _VectorCopy(unsafe { (*from).s.angles }, &mut fromAngles);
    }

    CalcEntitySpot(ctx, from, spot_t::SPOT_HEAD_LEAN, &mut eyes);

    CalcEntitySpot(ctx, ent, spot_t::SPOT_ORIGIN, &mut spot);
    _VectorSubtract(spot, eyes, &mut deltaVector);

    vectoangles(deltaVector, &mut angles);
    deltaAngles[0] = AngleDelta(fromAngles[0], angles[0]);
    deltaAngles[1] = AngleDelta(fromAngles[1], angles[1]);
    if deltaAngles[0].abs() <= vFOV as f32 && deltaAngles[1].abs() <= hFOV as f32 {
        return 1;
    }

    CalcEntitySpot(ctx, ent, spot_t::SPOT_HEAD, &mut spot);
    _VectorSubtract(spot, eyes, &mut deltaVector);
    vectoangles(deltaVector, &mut angles);
    deltaAngles[0] = AngleDelta(fromAngles[0], angles[0]);
    deltaAngles[1] = AngleDelta(fromAngles[1], angles[1]);
    if deltaAngles[0].abs() <= vFOV as f32 && deltaAngles[1].abs() <= hFOV as f32 {
        return 1;
    }

    CalcEntitySpot(ctx, ent, spot_t::SPOT_LEGS, &mut spot);
    _VectorSubtract(spot, eyes, &mut deltaVector);
    vectoangles(deltaVector, &mut angles);
    deltaAngles[0] = AngleDelta(fromAngles[0], angles[0]);
    deltaAngles[1] = AngleDelta(fromAngles[1], angles[1]);
    if deltaAngles[0].abs() <= vFOV as f32 && deltaAngles[1].abs() <= hFOV as f32 {
        return 1;
    }

    0
}

/// Raven `InVisrange`.
///
/// Raven: FIXME: make a calculate visibility for ents that takes into
/// account lighting, movement, turning, crouch/stand up, other anims, hide
/// brushes, etc.
/// Source: `oracle/oracle/codemp/game/NPC_senses.c:210-251`
pub fn InVisrange(
    ctx: GameContext<'_>,
    ent: *mut gentity_t,
) -> qboolean {
    let mut eyes = [0.0; 3];
    let mut spot = [0.0; 3];
    let mut deltaVector = [0.0; 3];

    let npc = unsafe { ctx.world.cast_mut().globals.NPC };
    let npcinfo = unsafe { ctx.world.cast_mut().globals.NPCInfo };

    CalcEntitySpot(ctx, npc, spot_t::SPOT_HEAD_LEAN, &mut eyes);
    CalcEntitySpot(ctx, ent, spot_t::SPOT_ORIGIN, &mut spot);
    _VectorSubtract(spot, eyes, &mut deltaVector);

    let visrange = unsafe { (*npcinfo).stats.visrange * (*npcinfo).stats.visrange };

    if VectorLengthSquared(deltaVector) > visrange {
        0
    } else {
        1
    }
}

/// Raven `NPC_CheckVisibility`.
///
/// Source: `oracle/oracle/codemp/game/NPC_senses.c:257-325`
pub fn NPC_CheckVisibility(
    ctx: GameContext<'_>,
    ent: *mut gentity_t,
    flags: c_int,
) -> visibility_t {
    // Visibility check flags
    const CHECK_PVS: c_int = 1;
    const CHECK_360: c_int = 2;
    const CHECK_FOV: c_int = 4;
    const CHECK_SHOOT: c_int = 8;
    const CHECK_VISRANGE: c_int = 16;

    // flags should never be 0
    if flags == 0 {
        return visibility_t::VIS_NOT;
    }

    let npc = unsafe { ctx.world.cast_mut().globals.NPC };
    let npcinfo = unsafe { ctx.world.cast_mut().globals.NPCInfo };

    // check PVS
    if (flags & CHECK_PVS) != 0 {
        if trap::InPVS(
            ctx.engine,
            unsafe { (*ent).r.currentOrigin },
            unsafe { (*npc).r.currentOrigin },
        ) == 0
        {
            return visibility_t::VIS_NOT;
        }
    }
    if (flags & (CHECK_360 | CHECK_FOV | CHECK_SHOOT)) == 0 {
        return visibility_t::VIS_PVS;
    }

    // check within visrange
    if (flags & CHECK_VISRANGE) != 0 {
        if InVisrange(ctx, ent) == 0 {
            return visibility_t::VIS_PVS;
        }
    }

    // check 360 degree visibility
    if (flags & CHECK_360) != 0 {
        if CanSee(ctx, ent) == 0 {
            return visibility_t::VIS_PVS;
        }
    }
    if (flags & (CHECK_FOV | CHECK_SHOOT)) == 0 {
        return visibility_t::VIS_360;
    }

    // check FOV
    if (flags & CHECK_FOV) != 0 {
        if InFOV(
            ctx,
            ent,
            npc,
            unsafe { (*npcinfo).stats.hfov },
            unsafe { (*npcinfo).stats.vfov },
        ) == 0
        {
            return visibility_t::VIS_360;
        }
    }

    if (flags & CHECK_SHOOT) == 0 {
        return visibility_t::VIS_FOV;
    }

    // check shootability
    if (flags & CHECK_SHOOT) != 0 {
        if CanShoot(ctx, ent, npc) == 0 {
            return visibility_t::VIS_FOV;
        }
    }

    visibility_t::VIS_SHOOT
}

/// Raven `G_CheckSoundEvents`.
///
/// Raven: NPC_CheckSoundEvents.
/// Source: `oracle/oracle/codemp/game/NPC_senses.c:332-386`
pub fn G_CheckSoundEvents(
    ctx: GameContext<'_>,
    self_: *mut gentity_t,
    maxHearDist: f32,
    ignoreAlert: c_int,
    mustHaveOwner: qboolean,
    minAlertLevel: c_int,
) -> c_int {
    let mut bestEvent = -1;
    let mut bestAlert = -1;
    let mut bestTime = -1;
    let max_hear_dist_squared = maxHearDist * maxHearDist;

    let world = unsafe { ctx.world.cast_mut() };

    for i in 0..world.level.numAlertEvents as usize {
        // are we purposely ignoring this alert?
        if i as c_int == ignoreAlert {
            continue;
        }
        // We're only concerned about sounds
        if world.level.alertEvents[i].r#type != alertEventType_e::AET_SOUND {
            continue;
        }
        // must be at least this noticeable
        if (world.level.alertEvents[i].level as i32) < minAlertLevel {
            continue;
        }
        // must have an owner?
        if mustHaveOwner != 0 && world.level.alertEvents[i].owner.is_null() {
            continue;
        }
        // Must be within range
        let dist = DistanceSquared(world.level.alertEvents[i].position, unsafe {
            (*self_).r.currentOrigin
        });

        // can't hear it
        if dist > max_hear_dist_squared {
            continue;
        }

        let radius = world.level.alertEvents[i].radius * world.level.alertEvents[i].radius;
        if dist > radius {
            continue;
        }

        if world.level.alertEvents[i].addLight != 0.0 {
            // a quiet sound, must have LOS to hear it
            if G_ClearLOS5(ctx, self_, world.level.alertEvents[i].position) == 0 {
                // no LOS, didn't hear it
                continue;
            }
        }

        // See if this one takes precedence over the previous one
        if world.level.alertEvents[i].level as i32 >= bestAlert
            || (world.level.alertEvents[i].level as i32 == bestAlert
                && world.level.alertEvents[i].timestamp >= bestTime)
        {
            bestEvent = i as c_int;
            bestAlert = world.level.alertEvents[i].level as i32;
            bestTime = world.level.alertEvents[i].timestamp;
        }
    }

    bestEvent
}

