///
/// Raven: NPC_CheckSightEvents.
/// Source: `oracle/oracle/codemp/game/NPC_senses.c:408-468`
pub fn G_CheckSightEvents(
    ctx: GameContext<'_>,
    self_: *mut gentity_t,
    hFOV: c_int,
    vFOV: c_int,
    maxSeeDist: f32,
    ignoreAlert: c_int,
    mustHaveOwner: qboolean,
    minAlertLevel: c_int,
) -> c_int {
    let mut bestEvent = -1;
    let mut bestAlert = -1;
    let mut bestTime = -1;
    let max_see_dist_squared = maxSeeDist * maxSeeDist;

    let world = unsafe { ctx.world.cast_mut() };

    for i in 0..world.level.numAlertEvents as usize {
        // are we purposely ignoring this alert?
        if i as c_int == ignoreAlert {
            continue;
        }
        // We're only concerned with sight events
        if world.level.alertEvents[i].r#type != alertEventType_e::AET_SIGHT {
            continue;
        }
        // must be at least this noticeable
        if (world.level.alertEvents[i].level as i32) < minAlertLevel {
            continue;
        }
        // must have an owner?
        if mustHaveOwner != 0 && world.level.alertEvents[i].owner.is_null() {
            continue;
        }

        // Must be within range
        let dist = DistanceSquared(world.level.alertEvents[i].position, unsafe {
            (*self_).r.currentOrigin
        });

        // can't see it
        if dist > max_see_dist_squared {
            continue;
        }

        let radius = world.level.alertEvents[i].radius * world.level.alertEvents[i].radius;
        if dist > radius {
            continue;
        }

        // Must be visible
        if InFOV2(ctx, world.level.alertEvents[i].position, self_, hFOV, vFOV) == 0 {
            continue;
        }

        if G_ClearLOS5(ctx, self_, world.level.alertEvents[i].position) == 0 {
            continue;
        }

        // See if this one takes precedence over the previous one
        if world.level.alertEvents[i].level as i32 >= bestAlert
            || (world.level.alertEvents[i].level as i32 == bestAlert
                && world.level.alertEvents[i].timestamp >= bestTime)
        {
            bestEvent = i as c_int;
            bestAlert = world.level.alertEvents[i].level as i32;
            bestTime = world.level.alertEvents[i].timestamp;
        }
    }

    bestEvent
}

/// Raven `G_CheckAlertEvents`.
///
/// Raven: NPC_CheckAlertEvents. NOTE: Should all NPCs create alertEvents too
/// so they can detect each other?
/// Source: `oracle/oracle/codemp/game/NPC_senses.c:478-530`
pub fn G_CheckAlertEvents(
    ctx: GameContext<'_>,
    self_: *mut gentity_t,
    checkSight: qboolean,
    checkSound: qboolean,
    maxSeeDist: f32,
    maxHearDist: f32,
    ignoreAlert: c_int,
    mustHaveOwner: qboolean,
    minAlertLevel: c_int,
) -> c_int {
    let mut bestSoundEvent = -1;
    let mut bestSightEvent = -1;
    let mut bestSoundAlert = -1;
    let mut bestSightAlert = -1;

    let world = unsafe { ctx.world.cast_mut() };

    if world.entities[0].health <= 0 {
        // player is dead
        return -1;
    }

    // get sound event
    bestSoundEvent = G_CheckSoundEvents(
        ctx,
        self_,
        maxHearDist,
        ignoreAlert,
        mustHaveOwner,
        minAlertLevel,
    );
    // get sound event alert level
    if bestSoundEvent >= 0 {
        bestSoundAlert = world.level.alertEvents[bestSoundEvent as usize].level as i32;
    }

    // get sight event
    if unsafe { !(*self_).NPC.is_null() } {
        bestSightEvent = G_CheckSightEvents(
            ctx,
            self_,
            unsafe { (*(*self_).NPC).stats.hfov },
            unsafe { (*(*self_).NPC).stats.vfov },
            maxSeeDist,
            ignoreAlert,
            mustHaveOwner,
            minAlertLevel,
        );
    } else {
        bestSightEvent = G_CheckSightEvents(
            ctx,
            self_,
            80,
            80,
            maxSeeDist,
            ignoreAlert,
            mustHaveOwner,
            minAlertLevel,
        );
    }
    // get sight event alert level
    if bestSightEvent >= 0 {
        bestSightAlert = world.level.alertEvents[bestSightEvent as usize].level as i32;
    }

    // return the one that has a higher alert (or sound if equal)
    if bestSightEvent >= 0 && bestSightAlert > bestSoundAlert {
        // valid best sight event, more important than the sound event
        // get the light level of the alert event for this checker
        let mut eyePoint = [0.0; 3];
        let mut sightDir = [0.0; 3];
        // get eye point
        CalcEntitySpot(ctx, self_, spot_t::SPOT_HEAD_LEAN, &mut eyePoint);
        _VectorSubtract(
            world.level.alertEvents[bestSightEvent as usize].position,
            eyePoint,
            &mut sightDir,
        );
        world.level.alertEvents[bestSightEvent as usize].light =
            world.level.alertEvents[bestSightEvent as usize].addLight
                + G_GetLightLevel(
                    world.level.alertEvents[bestSightEvent as usize].position,
                    sightDir,
                );
        // return the sight event
        return bestSightEvent;
    }
    // return the sound event
    bestSoundEvent
}

