/// Raven `G_CheckForDanger`.
///
/// Raven: FIXME: more bStates need to call this?
/// Source: `oracle/oracle/codemp/game/NPC_senses.c:537-567`
pub fn G_CheckForDanger(
    ctx: GameContext<'_>,
    self_: *mut gentity_t,
    alertEvent: c_int,
) -> qboolean {
    if alertEvent == -1 {
        return 0;
    }

    let world = unsafe { ctx.world.cast_mut() };

    if (world.level.alertEvents[alertEvent as usize].level as i32) >= AEL_DANGER as i32 {
        // run away!
        let owner = world.level.alertEvents[alertEvent as usize].owner;
        let owner_team = if !owner.is_null() && !unsafe { (*owner).client.is_null() } {
            Some(unsafe { (*(*owner).client).playerTeam })
        } else {
            None
        };

        let should_flee = if let Some(team) = owner_team {
            !owner.is_null()
                && owner != self_
                && unsafe { (*self_).client.is_null() }
                    == false
                && team != unsafe { (*(*self_).client).playerTeam }
        } else {
            owner.is_null()
        };

        if should_flee {
            if unsafe { !(*self_).NPC.is_null() } {
                if (unsafe { (*(*self_).NPC).scriptFlags } & SCF_DONT_FLEE) != 0 {
                    // can't flee
                    return 0;
                } else {
                    NPC_StartFlee(
                        ctx,
                        world.level.alertEvents[alertEvent as usize].owner,
                        world.level.alertEvents[alertEvent as usize].position,
                        world.level.alertEvents[alertEvent as usize].level as c_int,
                        3000,
                        6000,
                    );
                    return 1;
                }
            } else {
                return 1;
            }
        }
    }
    0
}

