/// Raven `ClearPlayerAlertEvents`.
///
/// Source: `oracle/oracle/codemp/game/NPC_senses.c:660-693`
pub fn ClearPlayerAlertEvents(ctx: GameContext<'_>) {
    const ALERT_CLEAR_TIME: c_int = 200;

    let world = unsafe { ctx.world.cast_mut() };
    let cur_num_alerts = world.level.numAlertEvents;
    let mut i = 0;
    // loop through them all (max 32)
    while i < cur_num_alerts {
        // see if the event is old enough to delete
        if world.level.alertEvents[i as usize].timestamp != 0
            && world.level.alertEvents[i as usize].timestamp + ALERT_CLEAR_TIME < world.level.time
        {
            // this event has timed out
            // drop the count
            world.level.numAlertEvents -= 1;
            // shift the rest down
            if world.level.numAlertEvents > 0 {
                // still have more in the array
                if (i + 1) < MAX_ALERT_EVENTS as c_int {
                    // Move elements down in the array
                    for j in i as usize..MAX_ALERT_EVENTS {
                        if j + 1 < MAX_ALERT_EVENTS {
                            world.level.alertEvents[j] = world.level.alertEvents[j + 1];
                        } else {
                            world.level.alertEvents[j] = alertEvent_t::default();
                        }
                    }
                }
            } else {
                // just clear this one... or should we clear the whole array?
                world.level.alertEvents[i as usize] = alertEvent_t::default();
            }
        }
        i += 1;
    }
    // make sure this never drops below zero... if it does, something very very bad happened
    assert!(world.level.numAlertEvents >= 0);

    if world.globals.eventClearTime < world.level.time {
        // this is just a 200ms debouncer so things that generate constant alerts (like corpses and missiles) add an alert every 200 ms
        world.globals.eventClearTime = world.level.time + ALERT_CLEAR_TIME;
    }
}

/// Raven `RemoveOldestAlert`.
///
/// Source: `oracle/oracle/codemp/game/NPC_senses.c:695-730`
pub fn RemoveOldestAlert(ctx: GameContext<'_>) -> qboolean {
    let world = unsafe { ctx.world.cast_mut() };

    let mut oldest_event = -1;
    let mut oldest_time = 16777216; // Q3_INFINITE
    let mut i;

    // loop through them all (max 32)
    i = 0;
    while i < world.level.numAlertEvents {
        // see if the event is old enough to delete
        if world.level.alertEvents[i as usize].timestamp < oldest_time {
            oldest_event = i;
            oldest_time = world.level.alertEvents[i as usize].timestamp;
        }
        i += 1;
    }
    if oldest_event != -1 {
        // drop the count
        world.level.numAlertEvents -= 1;
        // shift the rest down
        if world.level.numAlertEvents > 0 {
            // still have more in the array
            if (oldest_event + 1) < MAX_ALERT_EVENTS as c_int {
                // Move elements down in the array
                for j in (oldest_event as usize)..MAX_ALERT_EVENTS {
                    if j + 1 < MAX_ALERT_EVENTS {
                        world.level.alertEvents[j] = world.level.alertEvents[j + 1];
                    } else {
                        world.level.alertEvents[j] = alertEvent_t::default();
                    }
                }
            }
        } else {
            // just clear this one... or should we clear the whole array?
            world.level.alertEvents[oldest_event as usize] = alertEvent_t::default();
        }
    }
    // make sure this never drops below zero... if it does, something very very bad happened
    assert!(world.level.numAlertEvents >= 0);
    // return true if have room for one now
    if world.level.numAlertEvents < MAX_ALERT_EVENTS as c_int {
        1
    } else {
        0
    }
}

/// Raven `G_ClearLOS`.
///
/// Raven: Position to position.
/// Source: `oracle/oracle/codemp/game/NPC_senses.c:739-764`
pub fn G_ClearLOS(
    ctx: GameContext<'_>,
    self_: *mut gentity_t,
    start: vec3_t,
    end: vec3_t,
) -> qboolean {
    let mut tr = trace_t::default();
    let mut trace_count = 0;

    // FIXME: ENTITYNUM_NONE ok?
    trap::Trace(
        ctx.engine,
        &mut tr as *mut trace_t,
        &start as *const vec3_t,
        core::ptr::null(),
        core::ptr::null(),
        &end as *const vec3_t,
        ENTITYNUM_NONE,
        CONTENTS_OPAQUE,
    );
    while tr.fraction < 1.0 && trace_count < 3 {
        // can see through 3 panes of glass
        if (tr.entityNum as c_int) < ENTITYNUM_WORLD {
            let world = unsafe { ctx.world.cast_mut() };
            if tr.entityNum < MAX_GENTITIES as u32 {
                if !world.entities[tr.entityNum as usize].r.svFlags
                    & (SVF_GLASS_BRUSH as c_int)
                    != 0
                {
                    // can see through glass, trace again, ignoring me
                    trap::Trace(
                        ctx.engine,
                        &mut tr as *mut trace_t,
                        &tr.endpos as *const vec3_t,
                        core::ptr::null(),
                        core::ptr::null(),
                        &end as *const vec3_t,
                        tr.entityNum as c_int,
                        MASK_OPAQUE,
                    );
                    trace_count += 1;
                    continue;
                }
            }
        }
        return 0;
    }

    if tr.fraction == 1.0 {
        1
    } else {
        0
    }
}

/// Raven `G_ClearLOS2`.
///
/// Raven: Entity to position.
/// Source: `oracle/oracle/codemp/game/NPC_senses.c:767-774`
pub fn G_ClearLOS2(
    ctx: GameContext<'_>,
    self_: *mut gentity_t,
    ent: *mut gentity_t,
    end: vec3_t,
) -> qboolean {
    let mut eyes = [0.0; 3];

    CalcEntitySpot(ctx, ent, spot_t::SPOT_HEAD_LEAN, &mut eyes);

    G_ClearLOS(ctx, self_, eyes, end)
}

/// Raven `G_ClearLOS3`.
///
/// Raven: Position to entity. Look for the chest first, then the head.
/// Source: `oracle/oracle/codemp/game/NPC_senses.c:777-794`
pub fn G_ClearLOS3(
    ctx: GameContext<'_>,
    self_: *mut gentity_t,
    start: vec3_t,
    ent: *mut gentity_t,
) -> qboolean {
    let mut spot = [0.0; 3];

    // Look for the chest first
    CalcEntitySpot(ctx, ent, spot_t::SPOT_ORIGIN, &mut spot);

    if G_ClearLOS(ctx, self_, start, spot) != 0 {
        return 1;
    }

    // Look for the head next
    CalcEntitySpot(ctx, ent, spot_t::SPOT_HEAD_LEAN, &mut spot);

    if G_ClearLOS(ctx, self_, start, spot) != 0 {
        return 1;
    }

    0
}

