/// Raven `NPC_GetHFOVPercentage`.
///
/// Source: `oracle/oracle/codemp/game/NPC_senses.c:824-839`
pub fn NPC_GetHFOVPercentage(
    spot: vec3_t,
    from: vec3_t,
    facing: vec3_t,
    hFOV: f32,
) -> f32 {
    let mut deltaVector = [0.0; 3];
    let mut angles = [0.0; 3];

    _VectorSubtract(spot, from, &mut deltaVector);

    vectoangles(deltaVector, &mut angles);

    let delta = (AngleDelta(facing[1], angles[1])).abs();

    if delta > hFOV {
        0.0
    } else {
        (hFOV - delta) / hFOV
    }
}

/// Raven `NPC_GetVFOVPercentage`.
///
/// Source: `oracle/oracle/codemp/game/NPC_senses.c:847-862`
pub fn NPC_GetVFOVPercentage(
    spot: vec3_t,
    from: vec3_t,
    facing: vec3_t,
    vFOV: f32,
) -> f32 {
    let mut deltaVector = [0.0; 3];
    let mut angles = [0.0; 3];

    _VectorSubtract(spot, from, &mut deltaVector);

    vectoangles(deltaVector, &mut angles);

    let delta = (AngleDelta(facing[0], angles[0])).abs();

    if delta > vFOV {
        0.0
    } else {
        (vFOV - delta) / vFOV
    }
}

/// Raven `G_FindLocalInterestPoint`.
///
/// Source: `oracle/oracle/codemp/game/NPC_senses.c:871-907`
pub fn G_FindLocalInterestPoint(
    ctx: GameContext<'_>,
    self_: *mut gentity_t,
) -> c_int {
    const MAX_INTEREST_DIST: f32 = 256.0 * 256.0; // 65536.0

    let mut best_point = ENTITYNUM_NONE;
    let mut best_dist = 16777216.0; // Q3_INFINITE
    let mut eyes = [0.0; 3];
    let mut diff_vec = [0.0; 3];

    let world = unsafe { ctx.world.cast_mut() };

    CalcEntitySpot(ctx, self_, spot_t::SPOT_HEAD_LEAN, &mut eyes);
    for i in 0..world.level.numInterestPoints as usize {
        // Don't ignore portals?  If through a portal, need to look at portal!
        if trap::InPVS(ctx.engine, world.level.interestPoints[i].origin, eyes) != 0 {
            _VectorSubtract(world.level.interestPoints[i].origin, eyes, &mut diff_vec);
            if ((diff_vec[0].abs() + diff_vec[1].abs()) / 2.0) < 48.0
                && diff_vec[2].abs() > ((diff_vec[0].abs() + diff_vec[1].abs()) / 2.0)
            {
                // Too close to look so far up or down
                continue;
            }
            let dist = VectorLengthSquared(diff_vec);
            // Some priority to more interesting points
            // dist -= ((int)level.interestPoints[i].lookMode * 5) * ((int)level.interestPoints[i].lookMode * 5);
            if dist < MAX_INTEREST_DIST && dist < best_dist {
                if G_ClearLineOfSight(
                    ctx,
                    eyes,
                    world.level.interestPoints[i].origin,
                    unsafe { (*self_).s.number },
                    MASK_OPAQUE,
                ) != 0
                {
                    best_dist = dist;
                    best_point = i as c_int;
                }
            }
        }
    }
    if best_point != ENTITYNUM_NONE && !world.level.interestPoints[best_point as usize].target.is_null() {
        G_UseTargets2(ctx, self_, self_, world.level.interestPoints[best_point as usize].target);
    }
    best_point
}

/// Raven `SP_target_interest`.
///
/// Raven: `//QUAKED target_interest (1 0.8 0.5) (-4 -4 -4) (4 4 4)` — a
/// point that a squadmate will look at if standing still. `target` fires
/// when someone looks at this thing. FIXME: rename point_interest.
/// Source: `oracle/oracle/codemp/game/NPC_senses.c:915-934`
pub fn SP_target_interest(
    ctx: GameContext<'_>,
    self_: *mut gentity_t,
) {
    let world = unsafe { ctx.world.cast_mut() };

    if world.level.numInterestPoints >= MAX_INTEREST_POINTS as c_int {
        // ERROR: Too many interest points, limit is MAX_INTEREST_POINTS
        Com_Printf(b"ERROR:  Too many interest points, limit is %d\n\0".as_ptr() as *const c_char, MAX_INTEREST_POINTS as c_int);
        G_FreeEntity(ctx, self_);
        return;
    }

    _VectorCopy(
        unsafe { (*self_).r.currentOrigin },
        &mut world.level.interestPoints[world.level.numInterestPoints as usize].origin,
    );

    if !unsafe { (*self_).target.is_null() } && unsafe { *(*self_).target } != 0 {
        world.level.interestPoints[world.level.numInterestPoints as usize].target =
            G_NewString(unsafe { (*self_).target });
    }

    world.level.numInterestPoints += 1;

    G_FreeEntity(ctx, self_);
}
